#mob
/// <summary>
/// The MobPickOrderTypeReturn class handles the RMA Purchase Order data and posting logic.
/// </summary>
[TFMTableNameAttribute(tableStr(PurchTable),staticMethodStr(MobConstants,Pick))]
class MobPickOrderTypeReturn extends MobPickOrderType
{
    #mob

    Set orderSet;
    VendPackingSlipJour packingSlipJour;

}

Method.Source:
/// <summary>
///
/// </summary>
/// <param name = "_common"></param>
/// <returns></returns>
public str getBackendID(Common _common)
{
    PurchTable purchTable = _common;
    return tableStr(PurchTable) + '/' + fieldStr(PurchTable,PurchId) + '/' + purchTable.PurchId + '/' + MobConstants::Pick();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public Map parameterMap()
{
    Map ret;

    ret = super();

    ret.insert(extendedTypeStr(MobPickReturnOrders),'');

    return ret;
}

public Map getHeaderRecords(TFMRequestFiltersElement _filters, str _scannedValue)
{
    InventLocation  inventLocation;
    Map             returnMap = new Map(Types::string, Types::Record);
    Common			ref = _filters.getReferredRecord();

    if ( ref.tableId == tableNum(MobPackingStation))
    {
        return returnMap;
    }

    orderSet = new Set (Types::String);
    inventLocation = MobHelper::getAllowedInventLocations(curUserId());
    while select inventLocation where (inventLocation.InventLocationId == _filters.parmWarehouse() || _filters.parmWarehouse() == MobConstants::all())
    {
        // Check if sales orders are enabled for this warehouse
        if (MobHelper::IsPurchReturnEnabled(inventLocation.InventLocationId))
        {
            // Use the warehouse from the current iteration
            _filters.parmWarehouse(inventLocation.InventLocationId);
            returnMap = MobHelper::mergeMaps(returnMap,this.getPurchaseOrders(_filters,_scannedValue));
        }
    }

    return returnMap;
}

private Map getPurchaseOrders(TFMRequestFiltersElement _filters, PurchId _scannedValue)
{
    PurchTable              purchTable;
    Map                     returnMap = new Map (Types::String, Types::Record);
    Query                   q = new Query();
    QueryRun                qr;
    QueryBuildDataSource    qbdsPurchTable;
    QueryBuildDataSource    qbdsPurchLine;
    QueryBuildDataSource    qbdsInventDim;
    PurchID                 pID;
    int                     sorting;        
    InventLocationId        locationId;

    if (_filters.getFieldMap().exists(tableStr(ReferenceIdentity)))
    {
        return returnMap;
    }
    qbdsPurchTable = q.addDataSource( tableNum( PurchTable ) );
    qbdsPurchTable.addSortField(fieldNum(purchTable, PurchId), SortOrder::Descending);
    qbdsPurchTable.addRange(fieldNum(PurchTable, PurchStatus)).value( queryValue(PurchStatus::Backorder) );
    qbdsPurchTable.addRange(fieldNum(purchTable, DocumentState)).value( queryValue(VersioningDocumentState::Confirmed) );


    qbdsPurchLine = qbdsPurchTable.addDataSource( tableNum(purchLine) );
    qbdsPurchLine.joinMode( JoinMode::ExistsJoin );
    qbdsPurchLine.addLink(fieldNum(purchTable, PurchId), FieldNum(purchLine, PurchId));
    qbdsPurchLine.addRange(fieldNum(PurchLine, PurchStatus)).value(queryValue(PurchStatus::Backorder));
    qbdsPurchLine.addRange(fieldNum(PurchLine, PurchQty)).value('<0');
    qbdsInventDim = qbdsPurchLine.addDataSource(tableNum( InventDim ));
    qbdsInventDim.joinMode( JoinMode::ExistsJoin );
    qbdsInventDim.addLink( fieldNum(purchLine,InventDimId), fieldNum(InventDim,InventDimId));
    if (_filters.parmWarehouse())
    {

        qbdsInventDim.addRange(fieldNum(InventDim, InventSiteId)).value( queryValue(InventLocation::find(_filters.parmWarehouse()).InventSiteId) );
        qbdsInventDim.addRange(fieldNum(InventDim, inventLocationId)).value(queryValue(_filters.parmWarehouse()));
    }
    else
    {
        qbdsPurchLine.addRange(fieldNum(InventDim, inventLocationId)).value('');
    }

    if (_scannedValue)
    {
        qbdsPurchLine.addRange(fieldNum(purchLine,itemId)).value( queryValue(_scannedValue) );
    }

    TFMFilterAdditionsDataBinding::modifyQuery(methodStr(MobDocPickOrder,PickOrderFilters) + strReplace(_filters.getFieldValue(extendedTypeStr(TFMOrderTypes)),';',''),q,_filters);
    qr = new QueryRun( q );
    while(qr.next())
    {
        purchTable = qr.get(tableNum(purchTable));
        pID = purchTable.PurchId;
        if (orderSet.in(pID) || !this.anyRelevantDates(pID,_filters.parmDeliveryDate()))
        {
            continue;
        }

        locationId = this.getLocationID(pID);

        if (locationId && ( _filters.parmWarehouse() == MobConstants::All() || _filters.parmWarehouse() ) && MobInventLocationsGroupRights::existsUser(curUserId(), locationId) )
        {
            Sorting++;
            returnMap.insert(this.getBackendID(purchTable),purchTable);

        }
        orderSet.add(pID);
    }
    return returnMap;
}

private boolean anyRelevantDates(PurchID _pID, Date _deliveryDate)
{
    PurchLine purchLineChk;
    while select purchLineChk
            where purchLineChk.PurchId == _pID
                && purchLineChk.RemainInventPhysical < 0
                && ((purchLineChk.ConfirmedDlv && purchLineChk.ConfirmedDlv <= _deliveryDate) || (!purchLineChk.ConfirmedDlv && purchLineChk.DeliveryDate <= _deliveryDate))
    {

        return true;

    }
    return false;
}

private WMSLocationID getLocationID(PurchID _pID)
{
    PurchLine purchLineChk;
    while select purchLineChk
            where purchLineChk.PurchId == _pID
                && purchLineChk.RemainInventPhysical < 0
    {

        return purchLineChk.inventDim().inventLocationId;

    }
    return '';
}

/// <summary>
/// Method to indicate whether or not the user should be prompted for information when posting.
/// </summary>
/// <returns>A set of registration collectors to prompt the user with when posting.</returns>
public Map getPostPromptCollectors(str _backendID)
{
    Map ret;

    ret = super(_backendID);
    ret.insert(MobConstants::PackingSlip(),TFMRegistrationCollectorText::TextStepMap(false, 1,MobConstants::PackingSlip(),"@SYS128445", "@SYS128445","@SYS128445",new DictType(extendedTypeNum(ProductReceiptId)).stringLen(),false));

    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_backendID"></param>
/// <returns></returns>
public Map getLineRecords(TFMRequestGetOrderLinesElement _request)
{
    Map                 returnMap = new Map(Types::string, Types::Record);
    PurchId             purchId = this.getPurchId(_request.parmBackendID());//,2,strlen(backendId)); // Remove the prefix
    PurchLine           purchLine;
    InventLocationId    locationID;
    Date                latestFilterDate;

    if (! purchId || !PurchTable::exist(purchId))
    {
        throw error(strfmt(PurchTable::txtNotExist(),purchId));
    }
    //MobDocReceiveOrder::addPromptForPackingslip(_orderElement, "@SYS128445", "@SYS128445");

    locationID = this.getLatestLocation(_request);
    latestFilterDate = this.getLatestDeliveryDate(_request);
    while select purchLine
                where purchLine.PurchId == purchId &&
                      purchLine.PurchStatus == PurchStatus::Backorder &&
                      purchLine.RemainInventPhysical < 0 &&
                      purchLine.PurchQty < 0 &&
                      ((PurchLine.ConfirmedDlv && PurchLine.ConfirmedDlv <= latestFilterDate) || (!PurchLine.ConfirmedDlv && PurchLine.DeliveryDate <= latestFilterDate))
    {
        if(purchLine.isStocked() && (locationID == MobConstants::All() || locationID == PurchLine.inventDim().InventLocationId))
        {
            returnMap.insert(tableStr(purchLine) + ';' + int642Str(purchLine.RecId), purchLine);                
        }
    }
    return returnMap;
}

private str getLatestLocation(TFMRequestGetOrderLinesElement _request)
{
    TFMDocumentQueue dQueue;
    InventLocationId location = MobConstants::All();

    select firstonly RequestXML, DeviceId, DocumentType, RecID from dQueue order by CreatedDateTime desc
        where dQueue.DeviceId == _request.parmRoot().parmdeviceID() && dQueue.DocumentType == methodStr(MobDocPickOrder,GetPickOrders);
    if (dQueue.RecId)
    {
        Location = MobHelper::FilterXml2String(dQueue.RequestXML(),MobConstants::Warehouse());
    }
    return location;
}

private date getLatestDeliveryDate(TFMRequestGetOrderLinesElement _request)
{
    TFMDocumentQueue    dQueue;
    Date                retDate = MobHelper::today();

    select firstonly RequestXML, DeviceId, DocumentType, RecID from dQueue order by CreatedDateTime desc
        where dQueue.DeviceId == _request.parmRoot().parmdeviceID() && dQueue.DocumentType == methodStr(MobDocPickOrder,GetPickOrders);
    if (dQueue.RecId)
    {
        retDate = str2Date(MobHelper::FilterXml2String(dQueue.RequestXML(),MobConstants::DeliveryDate()),123);
    }
    return retDate;
}

