/// <param name = "_orderElement"></param>
/// <returns></returns>
public str post(str _backendID, XmlElement _orderElement)
{
    str ret;


    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_backendID"></param>
/// <param name = "_orderElement"></param>
/// <returns></returns>
public str postRequest(TFMRequestOrdersElement _orderElement)
{
    PurchFormLetter_PackingSlip purchFormLetter;
    PurchId                     purchId = this.getPurchId(_orderElement.parmBackendID());
    PackingSlipId               packingSlipId       = _orderElement.parmPackingSlip();
    str                         ret;        
    Map                         InventTransMap = new Map(Types::String,Types::Real);
    MapEnumerator               inventTransEnum;
    //Set                         lines;
    MobRegistrations            mobRegistrations;
    PurchTable                  purchTable = PurchTable::find(purchId);
    PurchLine                   purchLine;
    CreatedTransactionId        transID;

    if (! purchId || !PurchTable::exist(purchId))
    {
        throw error(strfmt(PurchTable::txtNotExist(),purchId));
    }
    //lines = MobHelper::xmlLines2Set(_orderElement);

    //TFMRegistrations::SaveRegistrationsSet(lines,TFMInventRefType::Purch,purchId,true);

    transID = MobRegistrations::SaveRequest(_orderElement.Lines(), MobInventRefType::Purch,purchId,true).CreatedTransactionId; // Moved iteration/registration of xml here

    while select forupdate mobRegistrations
                index OrderLineNumIdx
                where mobRegistrations.InventRefType == MobInventRefType::Purch &&
                      mobRegistrations.InventRefId  == purchId &&
                      mobRegistrations.handled == NoYes::No
    {
        mobRegistrations.pick();
        mobRegistrations.handled = NoYes::Yes;
        InventTransMap.insert(mobRegistrations.InventTransId, (InventTransMap.exists(mobRegistrations.InventTransId) ? InventTransMap.lookup(mobRegistrations.InventTransId) : 0) + mobRegistrations.Qty);
        mobRegistrations.Update();

    }

    InventTransEnum = InventTransMap.getEnumerator();
    while (InventTransEnum.moveNext())
    {
        purchLine       = purchLine::findInventTransId(InventTransEnum.currentKey(),true);
        purchLine.PurchReceivedNow = InventTransEnum.currentValue();
        purchLine.setInventReceivedNow();
        purchLine.Tax1099Amount = 0;
        purchLine.Tax1099StateAmount = 0;
        purchLine.update();
    }
    purchFormLetter = PurchFormLetter::construct(DocumentStatus::PackingSlip);
    purchFormLetter.update(purchTable,PackingSlipId,purchFormLetter.transDate(),PurchUpdate::ReceiveNow);

    if(!purchFormLetter.parmJournalRecord().RecId)
    {
        throw error(strFmt("@MobileWMS:UnableToPost", purchId));
    }
    select firstonly packingSlipJour where packingSlipJour.PackingSlipId == packingSlipId;

    return ret;
}
